import React, { useEffect, useState } from 'react';
import { api } from '../api';
import { useNavigate } from 'react-router-dom';

const AdminPage = () => {
    const [users, setUsers] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        api.getUsers().then(setUsers).catch(() => navigate('/'));
    }, [navigate]);

    const changeRole = async (id, newRole) => {
        await api.updateUser(id, { role: newRole });
        // Обновляем локально
        setUsers(users.map(u => u.id === id ? { ...u, role: newRole } : u));
    };

    const deleteUser = async (id) => {
        if (window.confirm("Удалить?")) {
            await api.deleteUser(id);
            setUsers(users.filter(u => u.id !== id));
        }
    };

    return (
        <div className="container" style={{padding:'20px'}}>
            <h2>Управление пользователями</h2>
            <button onClick={()=>navigate('/')}>Назад в магазин</button>
            <table style={{width:'100%', marginTop:'20px'}}>
                <thead><tr><th>Логин</th><th>Email</th><th>Роль</th><th>Действия</th></tr></thead>
                <tbody>
                    {users.map(u => (
                        <tr key={u.id}>
                            <td>{u.username}</td>
                            <td>{u.email}</td>
                            <td>
                                <select value={u.role} onChange={(e) => changeRole(u.id, e.target.value)}>
                                    <option value="user">User</option>
                                    <option value="seller">Seller</option>
                                    <option value="admin">Admin</option>
                                </select>
                            </td>
                            <td><button onClick={()=>deleteUser(u.id)} style={{color:'red'}}>Удалить</button></td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};
export default AdminPage;
